package crm

import (
	"example.com/domainry-m1-crm/backend/generated/schema"
	"testing"
)

func TestAdvanceTransitionPolicy(t *testing.T) {
	if !legalLeadTransition(schema.LeadStatusNew, schema.LeadStatusContacted) ||
		!legalLeadTransition(schema.LeadStatusContacted, schema.LeadStatusQualified) ||
		!legalLeadTransition(schema.LeadStatusQualified, schema.LeadStatusLost) {
		t.Fatal("declared legal transition was rejected")
	}
	if legalLeadTransition(schema.LeadStatusNew, schema.LeadStatusQualified) || legalLeadTransition(schema.LeadStatusConverted, schema.LeadStatusLost) {
		t.Fatal("illegal or terminal transition was accepted")
	}
}
