// This file is initial project-owned business source. Domainry will never overwrite it.
package crm

import (
	"context"
	capabilities "example.com/domainry-m1-crm/backend/generated/capabilities"
	"example.com/domainry-m1-crm/backend/generated/data"
	"example.com/domainry-m1-crm/backend/generated/schema"
	"time"
)

// ScanStaleContacted implements the project-owned lead.scan_stale_contacted Handler.
func ScanStaleContacted(ctx context.Context, caps capabilities.ScanStaleContactedCapabilities, input capabilities.ScanStaleContactedInput) (capabilities.ScanStaleContactedOutput, error) {
	evaluationTime := time.Now().UTC()
	if input.EvaluationTime != nil {
		evaluationTime = input.EvaluationTime.UTC()
	}
	location, err := time.LoadLocation("Asia/Shanghai")
	if err != nil {
		return capabilities.ScanStaleContactedOutput{}, err
	}
	localTime := evaluationTime.In(location)
	if localTime.Weekday() == time.Saturday || localTime.Weekday() == time.Sunday {
		return capabilities.ScanStaleContactedOutput{}, nil
	}
	cutoff := evaluationTime.Add(-7 * 24 * time.Hour).Format(time.RFC3339Nano)
	leads, err := caps.Lead.List(ctx, data.NewLeadQuery().WhereStatusEqual(schema.LeadStatusContacted).
		WhereUpdatedAtLessThan(cutoff).OrderByIDAscending().Page(1, 200))
	if err != nil {
		return capabilities.ScanStaleContactedOutput{}, err
	}
	if len(leads) == 0 {
		return capabilities.ScanStaleContactedOutput{}, nil
	}
	date := time.Date(localTime.Year(), localTime.Month(), localTime.Day(), 0, 0, 0, 0, location)
	dedupeKeys := make([]string, len(leads))
	for index, lead := range leads {
		dedupeKeys[index] = "followup:" + string(lead.ID) + ":" + date.Format(time.DateOnly)
	}
	existing, err := caps.FollowupReminder.List(ctx, data.NewFollowupReminderQuery().WhereDedupeKeyIn(dedupeKeys[0], dedupeKeys[1:]...).Page(1, 200))
	if err != nil {
		return capabilities.ScanStaleContactedOutput{}, err
	}
	existingKeys := make(map[string]bool, len(existing))
	for _, reminder := range existing {
		existingKeys[reminder.DedupeKey] = true
	}
	newLeads := make([]schema.Lead, 0, len(leads))
	newKeys := make([]string, 0, len(leads))
	leadIDs := make([]schema.LeadID, 0, len(leads))
	for index, lead := range leads {
		if existingKeys[dedupeKeys[index]] {
			continue
		}
		newLeads = append(newLeads, lead)
		newKeys = append(newKeys, dedupeKeys[index])
		leadIDs = append(leadIDs, lead.ID)
	}
	if len(newLeads) == 0 {
		return capabilities.ScanStaleContactedOutput{}, nil
	}
	recipients, err := caps.Lead.NotificationRecipientBatch(ctx, leadIDs)
	if err != nil {
		return capabilities.ScanStaleContactedOutput{}, err
	}
	creates := make([]schema.CreateFollowupReminder, len(newLeads))
	for index, lead := range newLeads {
		creates[index] = schema.CreateFollowupReminder{
			DedupeKey: newKeys[index], Lead: schema.NewFollowupReminderLeadReference(lead.ID),
			Recipient: recipients[index], ReminderDate: date,
		}
	}
	created, err := caps.FollowupReminder.CreateBatch(ctx, creates)
	if err != nil {
		return capabilities.ScanStaleContactedOutput{}, err
	}
	intents := make([]capabilities.ScanStaleContactedNotificationIntent, len(newLeads))
	for index, lead := range newLeads {
		companyName := lead.CompanyName
		intents[index] = capabilities.ScanStaleContactedNotificationIntent{
			EventType: "lead.followup_overdue", SourceEventID: "followup_reminder:" + string(created[index].ID),
			RecipientUserIDs: []string{recipients[index]}, SubjectObjectKey: "lead", SubjectRecordID: string(lead.ID),
			SubjectVersion: lead.UpdatedAt, DedupeKey: newKeys[index], GroupKey: "lead:" + string(lead.ID),
			Alert: true, OccurredAt: evaluationTime,
			Variables: []capabilities.ScanStaleContactedNotificationVariable{{Key: "company_name", StringValue: &companyName}},
		}
	}
	if _, err := caps.Notifications.DispatchBatch(ctx, intents); err != nil {
		return capabilities.ScanStaleContactedOutput{}, err
	}
	return capabilities.ScanStaleContactedOutput{}, nil
}
